return function(params,ctx)
 for attempt=1,2 do
  local a=ctx.run_agent{name="attempt-"..attempt,prompt="You MUST call read_invoice for INV-7 before answering. Then identify the duplicate payment. Do not claim a refund happened.",model=params.model,input=ctx.input,tools={"read_invoice"},controls={temperature=0,max_tokens=500},budget={max_steps=attempt==1 and 1 or 3}}
  if a.stop_reason=="final_completion" then return {attempts=attempt,answer=a.output} end
 end
 return {delivered=false}
end
